/// Word `col` of surface row `surface` (out-of-range types read row 19, as `Rider::step` clamps them).
pub const fn surf(surface: usize, col: usize) -> f32 {
    SURFACE_TABLE[if surface > 19 { 19 } else { surface }][col]
}

/// The two integer words of a row ([17] and [21]).
pub const fn surf_int(surface: usize, col: usize) -> u32 {
    surf(surface, col).to_bits()
}
